const YKS_DISI_KAYNAK_RE = /\b(KPSS|DGS|ALES|AGS|YDS|YÖKDİL|LGS|TUS|DUS|MEB)\b|\b(?:[1-9]|1[0-2])\.\s*S[ıi]n[ıi]f\b/i

const kaynakAdAnahtari = (ad: string) => ad.toLocaleLowerCase('tr')
  .replace(/^(3d|345|apotemi|bilgi sarmal|orijinal|barış|paraf|palme|karekök|limit|acil) yayınları\s+/i, '')
  .replace(/[’']/g, '')
  .replace(/\s+/g, ' ')
  .trim()

export const KAYNAK_KATALOGU: KaynakKatalogItem[] = KAYNAK_KATALOGU_RAW
  .filter(kaynak => !YKS_DISI_KAYNAK_RE.test(kaynak.ad))
  .filter((kaynak, index, liste) => index === liste.findIndex(diger => diger.urun_url === kaynak.urun_url || kaynakAdAnahtari(diger.ad) === kaynakAdAnahtari(kaynak.ad)))

export const KAYNAK_DERSLER = Array.from(new Set(KAYNAK_KATALOGU.map(kaynak => kaynak.ders)))
export const KAYNAK_YAYINEVLERI = Array.from(new Set(KAYNAK_KATALOGU.map(kaynak => kaynak.yayinevi))).sort((a, b) => yayineviOncelik(a) - yayineviOncelik(b) || a.localeCompare(b, 'tr'))
